         id TEXT PRIMARY KEY,
         atividadeId TEXT,
         inicio TEXT,
         fim TEXT
       )`);
 
       db.run(`CREATE TABLE IF NOT EXISTS atividades (
         id TEXT PRIMARY KEY,
         titulo TEXT,
         tipo TEXT,
         salaId TEXT,
         vagas INTEGER,
         situacao TEXT DEFAULT 'prevista'
       )`);
 
       db.run(`CREATE TABLE IF NOT EXISTS inscricoes (
         id TEXT PRIMARY KEY,
         atividadeId TEXT,
         participanteId TEXT,
         status TEXT,
         convocadaAte TEXT,
